# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DİNÎ HİTABETTE HUTBE VE VAAZ UYGULAMALARININ KARŞILAŞTIRMASI</text>\n  <rect x="25" y="50" width="310" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#1e40af">HUTBE (Minber Hitabeti)</text>\n  <text x="40" y="102" font-size="11" fill="#1e3a8a">• Mekân ve Duruş: Minberde ayakta okunur.</text>\n  <text x="40" y="124" font-size="11" fill="#1e3a8a">• Hüküm: Cuma hutbesi farz (namazın şartı),</text>\n  <text x="48" y="140" font-size="10.5" fill="#334155">bayram hutbesi ise sünnettir.</text>\n  <text x="40" y="162" font-size="11" fill="#1e3a8a">• Zaman: Cuma namazından önce; bayram</text>\n  <text x="48" y="178" font-size="10.5" fill="#334155">namazından sonra icra edilir.</text>\n  <text x="40" y="200" font-size="11" font-weight="bold" fill="#1d4ed8">• Şekil: İki hutbeden oluşur, arada</text>\n  <text x="48" y="216" font-size="10.5" font-weight="bold" fill="#1d4ed8">kısa bir oturuş (celse) yapılır.</text>\n\n  <rect x="365" y="50" width="310" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#92400e">VAAZ (Kürsü Hitabeti)</text>\n  <text x="380" y="102" font-size="11" fill="#78350f">• Mekân ve Duruş: Vaaz kürsüsünde oturarak.</text>\n  <text x="380" y="124" font-size="11" fill="#78350f">• Hüküm: Namazın geçerlilik şartı değildir,</text>\n  <text x="388" y="140" font-size="10.5" fill="#334155">irşat ve tebliğ görevidir.</text>\n  <text x="380" y="162" font-size="11" fill="#78350f">• Zaman: Cuma ve bayram namazlarından</text>\n  <text x="388" y="178" font-size="10.5" fill="#334155">önce veya kandil/mukabele vakitlerinde.</text>\n  <text x="380" y="200" font-size="11" font-weight="bold" fill="#b45309">• Şekil: Tek bölümlüdür, süresi ve</text>\n  <text x="388" y="216" font-size="10.5" font-weight="bold" fill="#b45309">konu anlatımı daha geniştir (25-30 dk).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CUMA HUTBESİNİN UYGULAMA AŞAMALARI VE BÖLÜMLERİ</text>\n  <rect x="20" y="50" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="125" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">1. Birinci Hutbe (Öğüt Bölümü)</text>\n  <text x="30" y="98" font-size="10.5" fill="#334155">• İç ezan sonrası ayağa kalkılır.</text>\n  <text x="30" y="118" font-size="10.5" font-weight="bold" fill="#166534">• Hamdele, Şehadet ve Salvele</text>\n  <text x="30" y="138" font-size="10.5" fill="#334155">• Eûzü-besmele ile konuyla</text>\n  <text x="38" y="152" font-size="10.5" fill="#334155">ilgili ayet ve hadis okunur.</text>\n  <text x="30" y="174" font-size="10.5" font-weight="bold" fill="#166534">• Türkçe Hutbe Metni (Vaaz/Öğüt):</text>\n  <text x="38" y="190" font-size="10" fill="#475569">\'Aziz Müminler / Muhterem</text>\n  <text x="38" y="204" font-size="10" fill="#475569">Müslümanlar!\' hitabıyla sunulur.</text>\n\n  <rect x="245" y="50" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. Ara Oturuş (Celse)</text>\n  <rect x="260" y="92" width="180" height="128" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="116" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">İki Hutbe Arası Oturuş</text>\n  <text x="350" y="138" text-anchor="middle" font-size="10.5" fill="#334155">Birinci hutbe bitince hatip</text>\n  <text x="350" y="154" text-anchor="middle" font-size="10.5" fill="#334155">minberde üç tesbih miktarı</text>\n  <text x="350" y="170" text-anchor="middle" font-size="10.5" fill="#334155">kısa bir süre oturur (Sünnet).</text>\n  <text x="350" y="194" text-anchor="middle" font-size="10" font-weight="bold" fill="#92400e">İçinden istiğfar ve dua eder,</text>\n  <text x="350" y="208" text-anchor="middle" font-size="10" font-weight="bold" fill="#92400e">sonra ikinci hutbeye kalkar.</text>\n\n  <rect x="470" y="50" width="210" height="190" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="575" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">3. İkinci Hutbe (Dua ve Ayet)</text>\n  <text x="480" y="98" font-size="10.5" fill="#334155">• Hamdele ve salvele okunur.</text>\n  <text x="480" y="120" font-size="10.5" fill="#334155">• Müminlerin bağışlanması, birlik,</text>\n  <text x="488" y="134" font-size="10.5" fill="#334155">huzur ve sağlık için dua edilir.</text>\n  <text x="480" y="158" font-size="10.5" font-weight="bold" fill="#6d28d9">• Son Ayet (Nahl, 16/90):</text>\n  <text x="488" y="174" font-size="10" fill="#475569">\'İnnallâhe ye\'muru bil-adli</text>\n  <text x="488" y="188" font-size="10" fill="#475569">vel-ihsâni ve îtâi zil-kurbâ...\'</text>\n  <text x="480" y="210" font-size="10.5" fill="#334155">• Kamet getirilir ve namaza geçilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HUTBE ÖN HAZIRLIĞI, MİNBER ÂDÂBI VE DEĞERLENDİRME ÖLÇÜTLERİ</text>\n  <rect x="25" y="50" width="310" height="190" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="180" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Ön Hazırlık ve Minber Âdâbı</text>\n  <text x="40" y="102" font-size="11" fill="#075985">• Arapça dua ve ayetlerin tecvitli provası.</text>\n  <text x="40" y="126" font-size="11" fill="#075985">• Türkçe metinde vurgu ve durak çalışması.</text>\n  <text x="40" y="150" font-size="11" fill="#075985">• Temiz kıyafet (cübbe-sarık) ve abdest.</text>\n  <text x="40" y="174" font-size="11" fill="#075985">• Minbere sağ ayakla vakur biçimde çıkma.</text>\n  <text x="40" y="198" font-size="11" font-weight="bold" fill="#0369a1">• Hutbe bitiminde sol ayakla inip</text>\n  <text x="48" y="214" font-size="10.5" font-weight="bold" fill="#0369a1">gecikmeden mihraba geçerek imamlık yapma.</text>\n\n  <rect x="365" y="50" width="310" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Etkili Hutbe Sunum İlkeleri</text>\n  <text x="380" y="102" font-size="11" fill="#14532d">• Göz Teması: Sürekli metne bağlı kalmayıp</text>\n  <text x="388" y="118" font-size="10.5" fill="#166534">cemaate doğrudan hitap etme.</text>\n  <text x="380" y="142" font-size="11" fill="#14532d">• Ses ve Diksiyon: İşitilebilir, doğal,</text>\n  <text x="388" y="158" font-size="10.5" fill="#166534">samimi ve anlamla uyumlu ses tonu.</text>\n  <text x="380" y="182" font-size="11" fill="#14532d">• Zaman Yönetimi: Cemaati yormayan</text>\n  <text x="388" y="198" font-size="10.5" fill="#166534">özlü ve veciz anlatım (10-15 dakika).</text>\n  <text x="380" y="220" font-size="11" font-weight="bold" fill="#15803d">• Birleştirici, müjdeleyici ve hikmetli dil.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
